import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Vector3 } = ctx.THREE;

  const group = new Group();
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
  };

  // Load the GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;

    // Copy materials and geometry from the loaded scene
    scene.traverse((node) => {
      if (node instanceof Mesh) {
        node.castShadow = true;
        node.receiveShadow = true;
      }
    });

    group.add(scene);
  });

  // Apply hover interaction: subtle rise-in
  group.userData.handlers = group.userData.handlers || {};

  group.userData.handlers.onHover = () => {
    gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  group.userData.handlers.onHoverEnd = () => {
    gsap.to(group.position, {
      y: config.scenePosition?.y ?? 0.7,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto'
    });
  };

  group.userData.handlers.onPress = () => {
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      overwrite: 'auto'
    });
  };

  group.userData.handlers.onPressEnd = () => {
    gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'power4.out',
      overwrite: 'auto'
    });
  };

  group.userData.handlers.onClick = () => {
    ctx.emit('hub-home.select', {});
  };

  // Set initial position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition[0],
      config.scenePosition[1],
      config.scenePosition[2]
    );
  }

  // Set initial rotation and scale
  if (config.rotation) {
    group.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  }
  if (config.scale) {
    group.scale.set(config.scale[0], config.scale[1], config.scale[2]);
  }

  return group;
}
